<?php
if(!defined('ABSPATH'))exit;
function dgs_mg_fmt($c){return str_replace('.','٫',dgs_fa_digits(dgs_mg_decimal($c)));}
function dgs_mg_label($p){return dgs_mg_periods((int)substr($p,5,2)>=7?substr($p,0,4).'-'.((int)substr($p,0,4)+1):((int)substr($p,0,4)-1).'-'.substr($p,0,4))[$p]??dgs_fa_digits($p);}
function dgs_mg_form($ctx,$op,$st,$student=0){$h='<form class="mg-form" method="post" action="'.esc_url(admin_url('admin-post.php')).'">'.wp_nonce_field('dgs_monthly_marks','dgs_mg_nonce',true,false);foreach(array('action'=>'dgs_monthly_marks','operation'=>$op,'year'=>$ctx['year'],'class_id'=>$ctx['class_id'],'subject_id'=>$ctx['subject_id'],'period'=>$ctx['period'],'revision'=>$st->revision,'student_id'=>$student,'request_token'=>wp_generate_uuid4()) as $k=>$v)$h.='<input type="hidden" name="'.esc_attr($k).'" value="'.esc_attr($v).'">';return $h;}
function dgs_mg_link($ctx,$extra=array()){return dgs_school_url('grades',$ctx['year'],array_merge(array('grade_pair'=>$ctx['class_id'].':'.$ctx['subject_id'],'grade_period'=>$ctx['period']),$extra));}
function dgs_mg_panel($year){
 if(!current_user_can('dgs_manage_education')&&!dgs_edu_role(get_current_user_id(),'dgs_teacher'))return dgs_mg_reader($year).dgs_grade_report($year,dgs_grade_context($year));
 $manager=current_user_can('dgs_manage_education');$pairs=dgs_grade_pairs($year);$options=array();$pair=null;foreach($pairs as $v)$options[$v->class_id.':'.$v->subject_id]=dgs_edu_grade_label($v->grade).' '.$v->title.' — '.$v->subject;$selected=dgs_att_get('grade_pair',(string)array_key_first($options));if(!isset($options[$selected]))$selected=(string)array_key_first($options);foreach($pairs as $v)if($selected===$v->class_id.':'.$v->subject_id)$pair=$v;
 $current=dgs_mg_effective($year);$period=dgs_grade_period(dgs_att_get('grade_period',$current?:substr($year,0,4).'-07'),$year)?:($current?:substr($year,0,4).'-07');$periods=dgs_mg_periods($year);
 $out='<div class="mg-page"><header class="mg-heading"><h2>'.dgs_portal_icon('clipboard').' ثبت نمرات ماهانه</h2><p>ثبت اختیاری نمره و رویداد برای دانش‌آموزان کلاس</p></header>';
 $out.='<section class="mg-card mg-filter"><form method="get" action="'.esc_url(dgs_page_url('portal')).'"><input type="hidden" name="dg_tab" value="grades"><input type="hidden" name="dg_year" value="'.esc_attr($year).'">'.dgs_edu_select('grade_pair','کلاس و درس',$options,$selected).dgs_edu_select('grade_period','ماه گزارش',$periods,$period).'<button class="dg-btn dg-btn-outline">نمایش</button></form></section>';
 if(!$pair)return $out.dgs_empty('هنوز کلاس و درس تخصیص‌یافته‌ای وجود ندارد.').'</div>';
 $ctx=array('year'=>$year,'class_id'=>(int)$pair->class_id,'subject_id'=>(int)$pair->subject_id,'period'=>$period);$st=dgs_mg_view_state($ctx);$deadline=dgs_mg_deadline($year,$period);$deadlineLabel=dgs_att_jdate($deadline->format('Y-m-d'));$addctx=$ctx;if(!$manager&&$current)$addctx['period']=$current;$addst=dgs_mg_view_state($addctx);
 $out.='<div class="mg-context"><span>کلاس: <b>'.esc_html($pair->title).'</b></span><span>درس: <b>'.esc_html($pair->subject).'</b></span><span>ماه گزارش: <b>'.esc_html($periods[$period]).'</b></span><span>مهلت: <b>'.esc_html(dgs_fa_digits($deadlineLabel)).'، ۲۳:۵۹</b></span><span>'.($st->status==='closed'?'نهایی‌شده':($st->status==='legacy'?'سابقه نسخه پیشین':($st->reopened?'بازگشایی‌شده':'در حال ثبت'))).'</span></div>';
 $out.='<p class="mg-notice mg-gold">'.dgs_portal_icon('info').' ثبت‌های جدید دبیر پس از مهلت '.esc_html($periods[$period]).' برای '.esc_html(dgs_mg_label(dgs_mg_next($period))).' محاسبه می‌شوند. تاریخ ثبت خودکار و بر اساس ساعت تهران است.</p><p class="mg-notice">اصلاح ماه بسته‌شده فقط توسط مدیریت و با ثبت دلیل انجام می‌شود. ماه گزارش، تاریخ ثبت جدید را تغییر نمی‌دهد.</p>';
 if(!$manager&&$st->status==='open'){$days=(int)ceil(($deadline->getTimestamp()-dgs_mg_now()->getTimestamp())/DAY_IN_SECONDS);if($days>=0&&$days<=3)$out.='<p class="mg-notice mg-gold" role="status">'.dgs_portal_icon('bell').' یادآوری: '.esc_html(dgs_fa_digits($days)).' روز تا مهلت نهایی‌سازی این ماه باقی مانده است.</p>';}
 if($manager){$out.='<details class="mg-card mg-management"><summary>تنظیم مهلت و کنترل ماه — مدیریت</summary>'.dgs_mg_form($ctx,'deadline',$st).'<div class="mg-form-grid"><label>مهلت این ماه (شمسی)<input name="deadline" dir="ltr" value="'.esc_attr($deadlineLabel).'" placeholder="1405-08-26" required></label><button class="dg-btn">ذخیره مهلت ماه</button></div><p>مهلت پیش‌فرض پایان ماه است. تغییر مهلت، ثبت‌های قبلی را جابه‌جا نمی‌کند؛ قفل قبلی نیز خودکار باز نمی‌شود.</p></form>';
 if($st->status==='legacy')$out.=dgs_mg_form($ctx,'import',$st).'<p>نمرات قبلی بدون تغییر محفوظ‌اند. با انتقال، هر نمره قبلی به عنوان یک ثبت پایه وارد دفتر می‌شود و بازه برای بررسی دوباره نهایی و کارنامه برای انتشار مجدد پیش‌نویس می‌شود.</p><label>دلیل انتقال<input name="reason" required maxlength="2000"></label><button class="dg-btn" data-mg-confirm="نمرات قبلی با حفظ سابقه به دفتر جدید منتقل و برای انتشار مجدد آماده شوند؟">انتقال نمرات قبلی به دفتر ثبت</button></form>';
 else $out.=dgs_mg_form($ctx,'reopen',$st).'<label>دلیل بازگشایی<input name="reason" required maxlength="2000"></label><button class="dg-btn dg-btn-outline" data-mg-confirm="ماه برای ویرایش دبیر باز و انتشار آن متوقف شود؟">بازگشایی ماه</button></form>';$out.='</details>';}
 $summary=dgs_mg_summary($ctx['class_id'],$ctx['subject_id'],$period,$year);$ids=array_keys($summary);$student=absint(dgs_att_get('mg_student'));if(!isset($summary[$student]))$student=$ids?(int)$ids[0]:0;$students=array();foreach($summary as $r)$students[$r['id']]=$r['name'];$has=count(array_filter($summary,function($r){return $r['entries']>0;}));
 $out.='<div class="mg-stats"><article><span>دانش‌آموزان کلاس</span><strong>'.esc_html(dgs_fa_digits(count($summary))).'</strong></article><article class="mg-green"><span>دارای ثبت</span><strong>'.esc_html(dgs_fa_digits($has)).'</strong></article><article class="mg-rose"><span>بدون ثبت</span><strong>'.esc_html(dgs_fa_digits(count($summary)-$has)).'</strong></article></div>';
 $canAdd=$addst->status!=='legacy'&&($manager||($current&&$addst->status==='open'));
 if($canAdd&&$students){$old=array();$notice=dgs_att_get('dg_notice');if(preg_match('/^[A-Za-z0-9]{24}$/D',$notice)){$k='dgs_mg_form_'.get_current_user_id().'_'.$notice;$old=get_transient($k);delete_transient($k);if(!is_array($old))$old=array();}
 $out.='<section class="mg-card"><h3>'.dgs_portal_icon('clipboard').' ثبت نمره و رویداد جدید</h3><div class="mg-context"><span>ثبت جدید برای: <b>'.esc_html(dgs_mg_label($addctx['period'])).'</b></span><span>کلاس: '.esc_html($pair->title).'</span><span>درس: '.esc_html($pair->subject).'</span></div>'.dgs_mg_form($addctx,'add',$addst,$student).'<div class="mg-target">'.dgs_edu_select('student_id','دانش‌آموز',$students,$student).'<label class="mg-all"><input type="checkbox" name="all" value="1" '.checked(($old['all']??'')==='1',true,false).'> انتخاب همه کلاس — یک ثبت جدید برای هر نفر</label></div><div class="mg-form-grid"><label>نمره جدید (۰ تا ۲۰)<input name="score" type="number" min="0" max="20" step="0.01" dir="ltr" autocomplete="off" value="'.esc_attr($old['score']??'').'" placeholder="نمره را وارد کنید"></label>'.dgs_edu_select('event_type','نوع رویداد',array(''=>'انتخاب کنید','positive'=>'مثبت','negative'=>'منفی'),$old['event_type']??'',false).'<label>مقدار رویداد<input name="event_amount" type="number" min="0.01" max="99999999.99" step="0.01" dir="ltr" autocomplete="off" value="'.esc_attr($old['event_amount']??'').'" placeholder="مقدار مثبت را وارد کنید"></label><label>توضیح / دلیل'.($manager?' مدیریتی (الزامی)':'').'<textarea name="note" maxlength="2000" '.($manager?'required':'').' placeholder="توضیح یا دلیل را وارد کنید">'.esc_textarea($old['note']??'').'</textarea></label></div><p class="mg-notice">ثبت نمره یا رویداد اختیاری است؛ فقط اطلاعات واردشده ذخیره می‌شوند.</p><p class="mg-required">برای رویداد منفی، نوشتن دلیل الزامی است.</p><div class="mg-actions"><button class="dg-btn" type="submit">'.dgs_portal_icon('check').' ثبت و آماده‌سازی ثبت بعدی</button><small>تاریخ ثبت: خودکار · انتخاب کلاس، درس و دانش‌آموز حفظ می‌شود.</small></div></form></section>';
 }else $out.='<p class="mg-notice">'.($addst->status==='legacy'?'این بازه سابقه قبلی دارد؛ مدیریت باید انتقال آن را تأیید کند.':(!$students?'دانش‌آموزی در این کلاس نیست.':'این ماه نهایی شده است؛ ثبت جدید در بازه بعدی یا پس از بازگشایی مدیریت ممکن است.')).'</p>';
 $out.='<section class="mg-card"><h3>'.dgs_portal_icon('grades').' نمرات و رویدادهای ثبت‌شده دانش‌آموزان</h3><label class="mg-search">'.dgs_portal_icon('search').'<input data-mg-search placeholder="جست‌وجوی دانش‌آموز..."></label><div class="mg-table-scroll"><table class="mg-table"><thead><tr><th>دانش‌آموز</th><th>نمره‌های ثبت‌شده</th><th>رویدادهای اعمال‌شده</th><th>میانگین نمره‌ها</th><th>جمع رویدادها</th><th>نمره فعلی ماه</th><th>جزئیات</th></tr></thead><tbody>';
 global $wpdb;$t=dgs_mg_tables();$recent=$wpdb->get_results($wpdb->prepare("SELECT id,student_id,kind,amount FROM {$t['entries']} WHERE class_id=%d AND subject_id=%d AND period=%s AND deleted=0 ORDER BY id DESC LIMIT 3000",$ctx['class_id'],$ctx['subject_id'],$period));$chips=array();foreach($recent as $r){$key=$r->student_id.':'.$r->kind;if(count($chips[$key]??array())<5)$chips[$key][]=dgs_mg_cents($r->amount);}
 foreach($summary as $r){$marks=$chips[$r['id'].':grade']??array();$events=$chips[$r['id'].':event']??array();$out.='<tr data-mg-name="'.esc_attr($r['name']).'" class="'.(!$r['entries']?'mg-no-entry':'').'"><td>'.esc_html($r['name']).(!$r['entries']?'<small class="mg-badge">بدون ثبت</small>':'').'</td><td>'.($marks?esc_html(implode('، ',array_map('dgs_mg_fmt',array_reverse($marks)))):'—').($r['count']>5?'<small>۵ ثبت اخیر</small>':'').'</td><td>';foreach(array_reverse($events) as $v)$out.='<span class="mg-chip '.($v<0?'mg-negative':'mg-positive').'" dir="ltr">'.esc_html(($v>0?'+':'').dgs_mg_fmt($v)).'</span>';$out.=(!$events?'—':'').'</td><td>'.($r['count']?esc_html(dgs_mg_fmt($r['mean'])):($r['entries']?'۰٫۰۰':'—')).'</td><td dir="ltr">'.esc_html(($r['events']>0?'+':'').dgs_mg_fmt($r['events'])).'</td><td><b class="mg-score">'.esc_html(dgs_mg_fmt($r['score'])).'</b></td><td><a class="mg-eye" aria-label="جزئیات '.esc_attr($r['name']).'" href="'.esc_url(dgs_mg_link($ctx,array('mg_student'=>$r['id']))).'#mg-history">'.dgs_portal_icon('eye').'</a></td></tr>';}
 $avg=$summary?intdiv(2*array_sum(array_column($summary,'score'))+count($summary),2*count($summary)):0;$out.='</tbody></table></div><p class="mg-notice">نمره فعلی ماه = میانگین نمره‌های دانش‌آموز + جمع رویدادها؛ حداقل ۰ و حداکثر ۲۰. بدون ثبت، نمره نهایی صفر است.</p><p class="mg-average">میانگین فعلی کلاس در این درس: <b>'.esc_html(dgs_mg_fmt($avg)).'</b></p><small>اعداد این جدول مربوط به همین درس و ماه گزارش‌اند؛ تا نهایی‌سازی و تأیید مدیریت، کارنامه منتشرشده نیستند.</small></section>';
 if($student)$out.=dgs_mg_history_card($ctx,$st,$student,$summary[$student]['name'],$manager);
 $out.='<section class="mg-card mg-final">';if($st->status==='open'&&($manager||$period===$current||$st->reopened))$out.=dgs_mg_form($ctx,'finalize',$st).'<input type="hidden" name="confirm" value="1"><button class="dg-btn dg-btn-outline" data-mg-confirm="نمرات این ماه نهایی و ویرایش دبیر قفل شود؟ دانش‌آموزان بدون ثبت، صفر می‌گیرند.">'.dgs_portal_icon('check').' ثبت نهایی نمرات ماه</button></form>';$out.='<p>ثبت دبیر ← نهایی‌سازی ماه ← بررسی و انتشار مدیریت</p><small>پس از مهلت، نهایی‌سازی خودکار انجام می‌شود؛ انتشار کارنامه فقط با تأیید مدیریت است.</small>';if($manager)$out.='<a class="dg-btn dg-btn-outline" href="'.esc_url(dgs_school_url('oversight',$year,array('os_month'=>$period,'os_class'=>$ctx['class_id']))).'">بررسی و انتشار کارنامه</a>';$out.='</section></div>';return $out;
}
function dgs_mg_history_card($ctx,$st,$student,$name,$manager){global $wpdb;$t=dgs_mg_tables();$page=max(1,absint(dgs_att_get('mg_page','1')));$rows=dgs_mg_history($ctx,$student,$page);$open=$st->status==='open'&&($st->reopened||dgs_mg_now()->getTimestamp()<=dgs_mg_deadline($ctx['year'],$ctx['period'])->getTimestamp());$out='<section class="mg-card" id="mg-history"><h3>جزئیات ثبت‌های '.esc_html($name).'</h3><p>تاریخ ثبت خودکار است و با ویرایش تغییر نمی‌کند. هر صفحه حداکثر ۵۰ ثبت.</p><div class="mg-table-scroll"><table class="mg-table"><thead><tr><th>نوع ثبت</th><th>مقدار</th><th>تاریخ خودکار</th><th>توضیح</th><th>عملیات</th></tr></thead><tbody>';foreach($rows as $r){$date=(new DateTimeImmutable($r->created_at,new DateTimeZone('UTC')))->setTimezone(new DateTimeZone('Asia/Tehran'));$out.='<tr><td>'.($r->kind==='grade'?'نمره':((float)$r->amount<0?'رویداد منفی':'رویداد مثبت')).'</td><td dir="ltr">'.esc_html(dgs_mg_fmt(dgs_mg_cents($r->amount))).'</td><td>'.esc_html(dgs_fa_digits(dgs_att_jdate($date->format('Y-m-d')).' '.$date->format('H:i'))).'</td><td>'.esc_html($r->note).'</td><td>';if($manager||($open&&(int)$r->actor_id===get_current_user_id())){$out.='<details><summary>ویرایش / حذف</summary>'.dgs_mg_form($ctx,'edit',$st,$student).'<input type="hidden" name="entry_id" value="'.(int)$r->id.'"><label>مقدار<input name="amount" type="number" step="0.01" '.($r->kind==='grade'?'min="0" max="20"':'').' value="'.esc_attr($r->amount).'" required></label><label>توضیح<input name="note" value="'.esc_attr($r->note).'" maxlength="2000"></label>'.($manager?'<label>دلیل اصلاح<input name="reason" required maxlength="2000"></label>':'').'<button class="dg-btn">ذخیره اصلاح</button></form>'.dgs_mg_form($ctx,'delete',$st,$student).'<input type="hidden" name="entry_id" value="'.(int)$r->id.'">'.($manager?'<label>دلیل حذف<input name="reason" required maxlength="2000"></label>':'').'<button class="mg-delete" data-mg-confirm="این ثبت حذف شود؟ سابقه تغییر محفوظ می‌ماند.">حذف ثبت</button></form></details>';}else $out.='قفل شده';$out.='</td></tr>';}$out.='</tbody></table></div>';if(!$rows)$out.='<p>ثبتی برای این دانش‌آموز وجود ندارد.</p>';$out.='<div class="mg-actions">';if($page>1)$out.='<a href="'.esc_url(dgs_mg_link($ctx,array('mg_student'=>$student,'mg_page'=>$page-1))).'#mg-history">صفحه قبل</a>';if(count($rows)===50)$out.='<a href="'.esc_url(dgs_mg_link($ctx,array('mg_student'=>$student,'mg_page'=>$page+1))).'#mg-history">صفحه بعد</a>';$out.='</div>';
 if($manager){$audit=$wpdb->get_results($wpdb->prepare("SELECT * FROM {$t['audit']} WHERE class_id=%d AND subject_id=%d AND period=%s ORDER BY id DESC LIMIT 30",$ctx['class_id'],$ctx['subject_id'],$ctx['period']));$out.='<details><summary>۳۰ تغییر اخیر این کلاس، درس و ماه — مدیریت</summary>';foreach($audit as $a){$actor=$a->actor_id?get_userdata($a->actor_id):null;$out.='<p><b>'.esc_html($a->operation).'</b> · '.esc_html($actor?$actor->display_name:'سیستم').' · '.esc_html($a->created_at).' UTC · '.esc_html($a->reason).'</p>';}$out.='</details>';}
 return $out.'</section>';
}
function dgs_mg_reader($year){
 $uid=get_current_user_id();$student=dgs_edu_role($uid,'dgs_student');$counselor=dgs_edu_role($uid,'dgs_counselor');if(!$student&&!$counselor)return '';global $wpdb;$t=dgs_mg_tables();$e=dgs_edu_tables();$p=dgs_grade_context($year);$args=array($year,$p);$where='';if($student){$where=' AND en.student_id=%d';$args[]=$uid;}else{$where=" AND EXISTS (SELECT 1 FROM {$e['counseling']} ca WHERE ca.student_id=en.student_id AND ca.school_year=en.school_year AND ca.counselor_id=%d)";$args[]=$uid;}
 $rows=$wpdb->get_results($wpdb->prepare("SELECT en.*,s.title AS subject,u.display_name FROM {$t['entries']} en JOIN {$e['subjects']} s ON s.id=en.subject_id JOIN {$wpdb->users} u ON u.ID=en.student_id WHERE en.school_year=%s AND en.period=%s AND en.deleted=0 $where ORDER BY en.id DESC LIMIT 200",$args));$out='<section class="mg-card"><h3>نمره‌ها و رویدادهای ثبت‌شده برای شما</h3><p>جزئیات ثبت دبیر قابل مشاهده است؛ نمره نهایی هر درس پس از انتشار مدیریت در کارنامه پایین دیده می‌شود.</p><div class="mg-table-scroll"><table class="mg-table"><thead><tr><th>دانش‌آموز</th><th>درس</th><th>نوع</th><th>مقدار</th><th>توضیح</th><th>تاریخ ثبت</th></tr></thead><tbody>';foreach($rows as $r)$out.='<tr><td>'.esc_html($r->display_name).'</td><td>'.esc_html($r->subject).'</td><td>'.($r->kind==='grade'?'نمره':'رویداد').'</td><td dir="ltr">'.esc_html(dgs_mg_fmt(dgs_mg_cents($r->amount))).'</td><td>'.esc_html($r->note).'</td><td>'.esc_html(dgs_mg_display_date($r->created_at)).'</td></tr>';return $out.'</tbody></table></div><small>۲۰۰ ثبت اخیر در ماه انتخابی</small></section>';
}
add_action('wp_enqueue_scripts',function(){if(!dgs_is_role_portal()||dgs_portal_tab()!=='grades')return;wp_register_style('dgs-monthly-marks',false,array(),DGS_VERSION);wp_enqueue_style('dgs-monthly-marks');wp_add_inline_style('dgs-monthly-marks',file_get_contents(DGS_PATH.'assets/monthly-grades.css'));wp_register_script('dgs-monthly-marks',false,array(),DGS_VERSION,true);wp_enqueue_script('dgs-monthly-marks');wp_add_inline_script('dgs-monthly-marks',file_get_contents(DGS_PATH.'assets/monthly-grades.js'));},60);

function dgs_mg_display_date($utc){$d=(new DateTimeImmutable($utc,new DateTimeZone('UTC')))->setTimezone(new DateTimeZone('Asia/Tehran'));return dgs_fa_digits(dgs_att_jdate($d->format('Y-m-d')).' '.$d->format('H:i'));}

// A quiet in-panel reminder on the teacher's other pages; no external messages.
add_filter('do_shortcode_tag',function($html,$tag){
 if($tag!=='daneshgaran_portal'||!dgs_is_role_portal()||dgs_portal_tab()==='grades'||current_user_can('dgs_manage_education')||!dgs_edu_role(get_current_user_id(),'dgs_teacher'))return $html;
 $year=dgs_edu_request_year();$p=dgs_mg_effective($year);if(!$p)return $html;$days=(int)ceil((dgs_mg_deadline($year,$p)->getTimestamp()-dgs_mg_now()->getTimestamp())/DAY_IN_SECONDS);if($days<0||$days>3)return $html;$pending=0;foreach(dgs_grade_pairs($year) as $pair){$st=dgs_mg_view_state(array('year'=>$year,'class_id'=>$pair->class_id,'subject_id'=>$pair->subject_id,'period'=>$p));if($st->status==='open')$pending++;}
